import { customisationSummary } from "../_shared/customisation.ts";
import {
  corsHeaders,
  jsonResponse,
  serviceClient,
  getCallerUserId,
  isAdmin,
  isVendorMember,
  errorMessage,
} from "../_shared/auth.ts";

// Customer GST tax invoice, one per boutique part of an order
// (vendor_order). The boutique is the seller: the invoice is issued in its
// legal name and GSTIN, generated by AllBoutiqs on its behalf. Generated
// once, on first request, then returned as-is - seller, buyer and tax
// details are snapshotted so it never changes afterwards.
//
// * Number: the boutique's own series, new every financial year:
//   AB0001/2627/0001 (next_boutique_invoice_number).
// * Prices include GST. Each product's rate comes from its category's HSN
//   code (gst_rate_for, which applies the apparel/footwear price band);
//   the order's discount is shared across all its lines by value, so each
//   boutique's invoice shows its share.
// * Same state (boutique's GSTIN state = delivery state) -> CGST + SGST,
//   otherwise IGST.
// * Shipping is part of the goods' supply: taxed at the rate of the
//   invoice's main (highest-value) product, under its HSN.

const round2 = (n: number) => Math.round(n * 100) / 100;

interface Line {
  line_no: number;
  order_item_id: string | null;
  description: string;
  hsn_code: string | null;
  size: string | null;
  color: string | null;
  sku: string | null;
  quantity: number;
  unit_price: number;
  discount: number;
  taxable_value: number;
  gst_rate: number;
  cgst_amount: number;
  sgst_amount: number;
  igst_amount: number;
  total: number;
}

function splitTax(amountInclusive: number, rate: number, intraState: boolean) {
  const taxable = round2(amountInclusive / (1 + rate / 100));
  const tax = round2(amountInclusive - taxable);
  const cgst = intraState ? round2(tax / 2) : 0;
  const sgst = intraState ? round2(tax - cgst) : 0;
  return { taxable, cgst, sgst, igst: intraState ? 0 : tax, total: round2(amountInclusive) };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { vendor_order_id } = await req.json();
    if (!vendor_order_id || typeof vendor_order_id !== "string") {
      return jsonResponse({ error: "vendor_order_id is required" }, 400);
    }

    const userId = await getCallerUserId(req);
    if (!userId) return jsonResponse({ error: "Unauthorized" }, 401);

    const supabase = serviceClient();

    const { data: vendorOrder, error: voErr } = await supabase
      .from("vendor_orders")
      .select("id, order_id, vendor_id, status, qc_status, dispatch_id, subtotal, shipping_cost")
      .eq("id", vendor_order_id)
      .maybeSingle();
    if (voErr) throw voErr;
    if (!vendorOrder) return jsonResponse({ error: "Order item not found" }, 404);

    const { data: order, error: orderErr } = await supabase
      .from("orders")
      .select("id, user_id, created_at, payment_method, payment_status, customer_name, shipping_address, subtotal, discount_code, discount_amount")
      .eq("id", vendorOrder.order_id)
      .maybeSingle();
    if (orderErr) throw orderErr;
    if (!order) return jsonResponse({ error: "Order not found" }, 404);

    // Warehouse staff print each boutique's invoice to go in the parcel.
    const authorized =
      order.user_id === userId ||
      (await isVendorMember(supabase, userId, vendorOrder.vendor_id)) ||
      (await isAdmin(supabase, userId)) ||
      (await supabase.rpc("can_operate_warehouse", { _user_id: userId })).data === true;
    if (!authorized) return jsonResponse({ error: "Forbidden" }, 403);

    const { data: existing, error: existingErr } = await supabase
      .from("invoices")
      .select("*")
      .eq("vendor_order_id", vendor_order_id)
      .maybeSingle();
    if (existingErr) throw existingErr;
    if (existing) {
      const { data: lines } = await supabase.from("invoice_lines").select("*").eq("invoice_id", existing.id).order("line_no");
      return jsonResponse({ invoice: existing, lines: lines ?? [] });
    }

    if (vendorOrder.status === "cancelled" || vendorOrder.status === "qc_failed" || vendorOrder.qc_status === "failed") {
      return jsonResponse({ error: "This item was cancelled - no invoice applies" }, 400);
    }
    // Online orders: once paid. Cash on Delivery: once the goods are on their
    // way to the customer (shipped, or passed the warehouse quality check and
    // being packed - warehouse staff put the invoice in the parcel).
    const goodsGoing =
      ["shipped", "out_for_delivery", "delivered", "ndr"].includes(vendorOrder.status) ||
      (vendorOrder.status === "at_warehouse" && vendorOrder.qc_status === "passed") ||
      !!vendorOrder.dispatch_id;
    if (order.payment_status !== "paid" && !(order.payment_method === "cod" && goodsGoing)) {
      return jsonResponse(
        {
          error:
            order.payment_method === "cod"
              ? "The invoice will be ready when this item is shipped"
              : "An invoice can only be generated for a paid order",
        },
        400,
      );
    }

    // ---------- seller (boutique) ----------
    const [{ data: vendor, error: vendorErr }, { data: kyc }] = await Promise.all([
      supabase.from("vendors").select("name, gst_number, pan_number, address").eq("id", vendorOrder.vendor_id).single(),
      supabase.from("vendor_kyc").select("legal_business_name, pan, gstin").eq("vendor_id", vendorOrder.vendor_id).maybeSingle(),
    ]);
    if (vendorErr) throw vendorErr;
    const gstin: string | null = kyc?.gstin ?? vendor.gst_number ?? null;
    if (!gstin) return jsonResponse({ error: "This boutique has no GSTIN on file - an admin needs to add it before invoicing" }, 422);
    const sellerStateCode = gstin.slice(0, 2);
    const { data: sellerState } = await supabase.from("indian_states").select("name").eq("gst_code", sellerStateCode).maybeSingle();

    // ---------- buyer / place of supply ----------
    const billingAddress = (order.shipping_address ?? {}) as Record<string, string>;
    const { data: posCode } = await supabase.rpc("gst_state_code", { _state: billingAddress.state ?? "" });
    if (!posCode) {
      return jsonResponse({ error: `Delivery state "${billingAddress.state ?? ""}" isn't recognised - an admin needs to correct the address` }, 422);
    }
    const { data: posState } = await supabase.from("indian_states").select("name").eq("gst_code", posCode).maybeSingle();
    const intraState = posCode === sellerStateCode;

    // ---------- lines ----------
    const { data: items, error: itemsErr } = await supabase
      .from("order_items")
      .select("id, product_id, product_title, variant_title, size, color, sku, quantity, price, customisation")
      .eq("vendor_order_id", vendorOrder.id)
      .order("created_at");
    if (itemsErr) throw itemsErr;
    if (!items?.length) return jsonResponse({ error: "No items found for this order" }, 400);

    const productIds = [...new Set(items.map((i) => i.product_id))];
    const { data: products } = await supabase
      .from("products")
      .select("id, categories(name, hsn_codes(id, code))")
      .in("id", productIds);
    const productById = new Map((products ?? []).map((p: any) => [String(p.id), p]));

    const itemsGross = round2(items.reduce((s, i) => s + Number(i.price) * i.quantity, 0));
    const orderGross = Number(order.subtotal) || itemsGross;
    const orderDiscount = Number(order.discount_amount) || 0;

    const lines: Line[] = [];
    for (const [idx, item] of items.entries()) {
      const product = productById.get(String(item.product_id));
      const hsn = product?.categories?.hsn_codes;
      if (!hsn?.id) {
        const where = product?.categories?.name ? `category "${product.categories.name}"` : `"${item.product_title}" (no category)`;
        return jsonResponse({ error: `No HSN code for ${where} - set it in Admin > Categories before invoicing` }, 422);
      }
      const gross = Number(item.price) * item.quantity;
      const discount = orderGross > 0 ? round2((orderDiscount * gross) / orderGross) : 0;
      const { data: rate, error: rateErr } = await supabase.rpc("gst_rate_for", {
        _hsn_code_id: hsn.id,
        _unit_price: (gross - discount) / item.quantity,
      });
      if (rateErr) throw rateErr;
      const t = splitTax(gross - discount, Number(rate), intraState);
      lines.push({
        line_no: idx + 1,
        order_item_id: item.id,
        description:
          (item.variant_title ? `${item.product_title} (${item.variant_title})` : item.product_title) +
          (item.customisation ? ` - Customised: ${customisationSummary(item.customisation)}` : ""),
        hsn_code: hsn.code,
        size: item.size,
        color: item.color,
        sku: item.sku,
        quantity: item.quantity,
        unit_price: Number(item.price),
        discount,
        taxable_value: t.taxable,
        gst_rate: Number(rate),
        cgst_amount: t.cgst,
        sgst_amount: t.sgst,
        igst_amount: t.igst,
        total: t.total,
      });
    }

    const shipping = Number(vendorOrder.shipping_cost) || 0;
    if (shipping > 0) {
      const main = [...lines].sort((a, b) => b.total - a.total)[0];
      const t = splitTax(shipping, main.gst_rate, intraState);
      lines.push({
        line_no: lines.length + 1,
        order_item_id: null,
        description: "Shipping charges",
        hsn_code: main.hsn_code,
        size: null,
        color: null,
        sku: null,
        quantity: 1,
        unit_price: shipping,
        discount: 0,
        taxable_value: t.taxable,
        gst_rate: main.gst_rate,
        cgst_amount: t.cgst,
        sgst_amount: t.sgst,
        igst_amount: t.igst,
        total: t.total,
      });
    }

    const sum = (k: keyof Line) => round2(lines.reduce((s, l) => s + Number(l[k]), 0));
    const issuedAt = new Date();
    const { data: invoiceNumber, error: numErr } = await supabase.rpc("next_boutique_invoice_number", {
      _vendor_id: vendorOrder.vendor_id,
      _at: issuedAt.toISOString(),
    });
    if (numErr) throw numErr;

    const { data: invoice, error: insertErr } = await supabase
      .from("invoices")
      .insert({
        invoice_number: invoiceNumber,
        vendor_order_id: vendorOrder.id,
        order_id: order.id,
        vendor_id: vendorOrder.vendor_id,
        issued_at: issuedAt.toISOString(),
        order_number: `#${order.id.slice(0, 8).toUpperCase()}`,
        order_date: order.created_at,
        subtotal: itemsGross,
        shipping_cost: shipping,
        discount_code: order.discount_code,
        discount_amount: sum("discount"),
        taxable_value: sum("taxable_value"),
        cgst_amount: sum("cgst_amount"),
        sgst_amount: sum("sgst_amount"),
        igst_amount: sum("igst_amount"),
        tax_amount: round2(sum("cgst_amount") + sum("sgst_amount") + sum("igst_amount")),
        total: sum("total"),
        supply_type: intraState ? "intra_state" : "inter_state",
        seller_name: vendor.name,
        seller_legal_name: kyc?.legal_business_name ?? vendor.name,
        seller_gstin: gstin,
        seller_pan: kyc?.pan ?? vendor.pan_number ?? gstin.slice(2, 12),
        seller_address: vendor.address,
        seller_state: sellerState?.name ?? null,
        seller_state_code: sellerStateCode,
        billing_name: order.customer_name,
        billing_address: order.shipping_address,
        billing_state: posState?.name ?? billingAddress.state ?? null,
        place_of_supply_code: posCode,
      })
      .select("*")
      .single();
    if (insertErr) throw insertErr;

    const { error: linesErr } = await supabase.from("invoice_lines").insert(lines.map((l) => ({ ...l, invoice_id: invoice.id })));
    if (linesErr) {
      await supabase.from("invoices").delete().eq("id", invoice.id);
      throw linesErr;
    }

    return jsonResponse({ invoice, lines });
  } catch (e) {
    console.error("generate-invoice error", e);
    return jsonResponse({ error: errorMessage(e) }, 500);
  }
});
